content:
{
  "root_cause": "The datepicker remains shown when tabbing out of the input, causing the Vanilla Calendar Pro to prevent the Tab key press to keep focus trapped within the calendar.",
  "repair_strategy": "Add a focusout listener to the input that hides the datepicker when focus leaves the input unless it is moving to the calendar, ensuring the datepicker is hidden before the focus changes to the next field.",
  "edits": [
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
",
      "after": "  protected declare _element: HTMLElement & { value: string }
  protected declare _config: DatepickerConfig
  protected declare _calendar: Calendar | null
  protected declare _isShown: boolean
  protected declare _isInput: boolean
  protected declare _isInline: boolean
  protected declare _boundInput: HTMLInputElement | null
  protected declare _positionElement: HTMLElement
  protected declare _displayElement: HTMLElement | false | null
  protected declare _themeObserver: MutationObserver | null
  protected declare _themeAncestor: Element | null | undefined
  protected declare _onOutside: (event: Event) => void
  protected declare _onTriggerClick: () => void
  protected declare _onFocusout: ((event: FocusEvent) => void) | null
"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false

    this._initCalendar()
  }
",
      "after": "  constructor(element?: string | Element | null, config?: Partial<DatepickerConfig> | null) {
    super(element, config)

    this._calendar = null
    this._isShown = false
    this._onFocusout = null

    this._initCalendar()
  }
"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    this._setupDismiss()

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }
",
      "after": "    this._setupDismiss()

    // Hide datepicker when losing focus unless focus is moving to the calendar
    this._onFocusout = (event: FocusEvent) => {
      if (!this._isShown) {
        return
      }
      const calendarMainElement = this._calendar?.context?.mainElement
      if (calendarMainElement && calendarMainElement.contains(event.relatedTarget as Node)) {
        return
      }
      this.hide()
    }

    EventHandler.on(this._element, 'focusout', this._onFocusout)

    // Set initial value if input has a value
    if (this._isInput && this._element.value) {
      this._parseInputValue()
    }

    // Populate input/display with preselected dates
    this._updateDisplayWithSelectedDates()
  }
"
    },
    {
      "path": "js/src/datepicker.ts",
      "sha256": "333ada052b9200667edf9078b105036dee5c1406a86e3865f6534e2ddb18c53a",
      "before": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }
",
      "after": "    if (this._onTriggerClick) {
      EventHandler.off(this._positionElement, EVENT_CLICK, this._onTriggerClick)
    }

    if (this._onFocusout) {
      EventHandler.off(this._element, 'focusout', this._onFocusout)
      this._onFocusout = null
    }

    if (this._calendar) {
      this._calendar.destroy()
    }

    this._calendar = null
    super.dispose()
  }
"
  ],
  "expected_accessibility_effect": "Tab key will now move focus from the departure date field to the passengers field as expected.",
  "functional_risks": [
    "Hiding the datepicker on focusout might interfere with users who navigate away from the input using means other than Tab (e.g., mouse click on another field) if the datepicker is still needed? But hiding on blur is common.",
    "If the user clicks on the calendar, the focusout event on the input will fire, but we check if the relatedTarget is in the calendar and avoid hiding in that case."
  ],
  "verification_requirements": [
    "Verify that pressing Tab from the departure date field moves focus to the passengers field.",
    "Verify that the datepicker is hidden when focus leaves the input unless moving to the calendar.",
    "Verify that clicking on a date in the calendar does not hide the calendar prematurely.",
    "Verify that the datepicker still functions correctly for mouse users."
  ]
}
